import React from 'react'
import Link from 'react-router-dom'

function CartButton() {
    return (
        <nav>
            <button
                style={{
                    padding: '10px 20px',
                    fontSize: '18px',
                    backgroundColor: '#007bff',
                    color: 'white',
                    border: 'none',
                    borderRadius: '5px',
                    cursor: 'pointer',
                    whiteSpace: 'nowrap',
                    height: '50px',
                }}>
                aS
            </button>
        </nav>
    )
}

export default CartButton;
